// Policy module: one place to answer "can user do action on resource?"
const policies = {
  "invoice:read":    (u, inv) => u.tenantId === inv.tenantId,
  "invoice:approve": (u, inv) => u.tenantId === inv.tenantId &&
                                 u.roles.includes("finance") &&
                                 inv.createdBy !== u.id,   // separation of duties
};

export function authorize(user, action, resource) {
  const rule = policies[action];
  if (!rule || !rule(user, resource)) throw new ForbiddenError(action); // deny by default
}

