async function refresh(presented) {
  const hash = sha256(presented);
  const token = await db.refreshTokens.findByHash(hash);
  if (!token || token.expiresAt < new Date()) throw new Unauthorized();

  if (token.usedAt) {
    // reuse of a rotated token: assume theft, kill the whole family
    await db.refreshTokens.revokeFamily(token.familyId);
    await audit.log("refresh_token_reuse", { userId: token.userId });
    throw new Unauthorized();
  }

  const next = crypto.randomBytes(32).toString("base64url");
  await db.transaction(async (tx) => {
    await tx.refreshTokens.markUsed(token.id);
    await tx.refreshTokens.insert({
      hash: sha256(next), userId: token.userId, familyId: token.familyId,
      expiresAt: minDate(addDays(new Date(), 14), token.familyExpiresAt), // absolute cap
    });
  });
  return { accessToken: await signAccessToken(token.userId), refreshToken: next };
}

